// SparkReportDetailModal — v8.0 SPARK IA Insights Trends deep-dive modal.
//
// Each report renders a rich body (KPI tiles, tables, breakdowns) plus the
// shared dark ARGUS observations box. The dispatch on reportKey lives in
// this file rather than a separate render module — SPARK's per-report
// content is more compact than ARION's so a single file is manageable.
//
// Architecture:
//   - Header: title · period · score chip · close
//   - Per-report rich body (renderSparkBody dispatch)
//   - ARGUS observations box (from rule library output)
//   - Footer: generated by ARGUS

import { X } from "lucide-react";
import { MonthlyScoreBars, MIN_HISTORY_PERIODS } from "./MonthlyScoreBars";
import { ArgusObservationsBox } from "./ArgusObservationsBox";
import { evaluateRules, type InsightRule } from "./insightRules";
import { SPARK_CONTACT_HEALTH_RULES } from "./sparkContactHealthRules";
import { SPARK_LEAD_PIPELINE_RULES } from "./sparkLeadPipelineRules";
import { SPARK_CAMPAIGN_PERF_RULES } from "./sparkCampaignPerfRules";
import {
  SPARK_MARKETING_ATTRIB_RULES,
  SPARK_SEGMENTATION_RULES,
  SPARK_AUTOMATION_EFF_RULES,
  SPARK_RETENTION_RISK_RULES,
  SPARK_REVENUE_ATTRIB_RULES,
} from "./sparkRemainingRules";

interface SparkReportAnalysis {
  score: number;
  scoreInputs: Array<{ key: string; value: number | string | null; weight: number; note?: string }>;
  observations: string[];
  actions: string[];
  contextNote?: string;
}

interface SparkMeta {
  key: string;
  label: string;
  question: string;
  icon: any;
  weight: number;
}

interface Props {
  reportKey: string;
  meta: SparkMeta;
  report: SparkReportAnalysis;
  history?: Array<{ period_end: string; score: number }>;
  /** SparkEngineInput shape — all data the engines + rule libraries need. */
  inputs: any;
  /** Optional period label override. */
  periodLabel?: string;
  /** Tenant / workspace label for the ARGUS box header. */
  tenantLabel?: string;
  onClose: () => void;
}

/** Per-report rule-library lookup. As each library is built, add it here. */
const SPARK_RULES_BY_REPORT: Record<string, InsightRule[] | undefined> = {
  contact_health:   SPARK_CONTACT_HEALTH_RULES,
  lead_pipeline:    SPARK_LEAD_PIPELINE_RULES,
  campaign_perf:    SPARK_CAMPAIGN_PERF_RULES,
  marketing_attrib: SPARK_MARKETING_ATTRIB_RULES,
  segmentation:     SPARK_SEGMENTATION_RULES,
  automation_eff:   SPARK_AUTOMATION_EFF_RULES,
  retention_risk:   SPARK_RETENTION_RISK_RULES,
  revenue_attrib:   SPARK_REVENUE_ATTRIB_RULES,
};

function bandColor(score: number): string {
  if (score >= 70) return "#16A34A";
  if (score >= 50) return "#EAB308";
  if (score > 0)   return "#DC2626";
  return "#94A3B8";
}

export function SparkReportDetailModal({
  reportKey,
  meta,
  report,
  history = [],
  inputs,
  periodLabel,
  tenantLabel,
  onClose,
}: Props) {
  const Icon = meta.icon;
  const scoreColor = bandColor(report.score);

  // v8.0 — when a rule library exists for this report, use it instead of
  // the engine's static observations. Fall back to engine output for
  // reports not yet migrated.
  const rules = SPARK_RULES_BY_REPORT[reportKey];
  let observations = report.observations;
  let actions = report.actions;
  if (rules) {
    const fired = evaluateRules(rules, inputs, { maxObservations: 8, maxActions: 5 });
    observations = fired.observations;
    actions = fired.actions;
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
    >
      {/* F-107 — "report" standard canvas. Bespoke header retained. */}
      <div
        className="bg-white rounded-lg shadow-2xl flex flex-col"
        style={{ width: "min(1400px, 94vw)", height: "90vh" }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-start justify-between gap-3 border-b border-slate-200 px-6 py-4 flex-shrink-0">
          <div className="flex items-start gap-3 min-w-0 flex-1">
            <div
              className="flex-shrink-0 h-10 w-10 rounded-full flex items-center justify-center"
              style={{ background: `${scoreColor}1A`, color: scoreColor }}
            >
              <Icon className="h-5 w-5" />
            </div>
            <div className="min-w-0">
              <h2 className="text-lg font-bold text-slate-900 truncate">{meta.label}</h2>
              <p className="text-xs text-slate-500 mt-0.5">{periodLabel || meta.question}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 flex-shrink-0">
            <div className="text-right">
              <div className="text-2xl font-bold tabular-nums" style={{ color: scoreColor }}>{report.score}</div>
              <div className="text-[9px] uppercase text-slate-400">/ 100</div>
            </div>
            <button
              onClick={onClose}
              className="p-1.5 hover:bg-slate-100 rounded text-slate-500"
              aria-label="Close"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
          {/* Score history */}
          {history.length >= MIN_HISTORY_PERIODS && (
            <div>
              <div className="flex items-center justify-between mb-1">
                <div className="text-[10px] uppercase font-semibold tracking-wide text-slate-500">Score history</div>
                <div className="text-[9px] text-slate-400">{history.length} period{history.length === 1 ? "" : "s"}</div>
              </div>
              <MonthlyScoreBars data={history} width={680} height={92} />
            </div>
          )}

          {/* Per-report rich body */}
          {renderSparkBody(reportKey, inputs, report)}

          {/* ARGUS observations box */}
          <ArgusObservationsBox
            observations={observations}
            actions={actions}
            reportLabel={meta.label}
            tenantLabel={tenantLabel}
            periodLabel={periodLabel}
          />
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between border-t border-slate-200 px-6 py-3 bg-slate-50 rounded-b-lg flex-shrink-0">
          <div className="text-[11px] text-slate-500">
            Generated by{" "}
            <span className="font-semibold" style={{ color: "#A3E635" }}>ARGUS</span>
            {periodLabel && <> · {periodLabel.split("·")[0].trim()}</>}
          </div>
          <button
            onClick={onClose}
            className="px-4 py-1.5 text-xs bg-slate-900 text-white rounded hover:bg-slate-800"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

// ── Per-report rich body sections ────────────────────────────────────
function renderSparkBody(reportKey: string, inputs: any, report: SparkReportAnalysis) {
  switch (reportKey) {
    case "contact_health":   return <ContactHealthBody inputs={inputs} />;
    case "lead_pipeline":    return <LeadPipelineBody inputs={inputs} />;
    case "campaign_perf":    return <CampaignPerfBody inputs={inputs} />;
    case "marketing_attrib": return <MarketingAttribBody inputs={inputs} />;
    case "segmentation":     return <SegmentationBody inputs={inputs} />;
    case "automation_eff":   return <AutomationEffBody inputs={inputs} />;
    case "retention_risk":   return <RetentionRiskBody inputs={inputs} />;
    case "revenue_attrib":   return <RevenueAttribBody inputs={inputs} />;
    default:                 return <GenericBody report={report} />;
  }
}

// ── Campaign Performance rich body ───────────────────────────────────
function CampaignPerfBody({ inputs }: { inputs: any }) {
  const ev: Record<string, number> = Object.fromEntries((inputs?.email_engagement || []).map((e: any) => [e.event_type, Number(e.n || 0)]));
  const sends = Number(inputs?.campaign_recent?.sent || 0);
  const delivered = Math.max(0, Number(ev.delivered || sends) - Number(ev.bounced || 0));
  const opens = Number(ev.opened || 0);
  const clicks = Number(ev.clicked || 0);
  const bounces = Number(ev.bounced || 0);
  const unsubs = Number(ev.unsubscribed || 0);
  const complaints = Number(ev.complained || ev.spam || 0);
  const openRate = delivered > 0 ? (opens / delivered) * 100 : 0;
  const clickRate = delivered > 0 ? (clicks / delivered) * 100 : 0;
  const ctorRate = opens > 0 ? (clicks / opens) * 100 : 0;
  const bounceRate = sends > 0 ? (bounces / sends) * 100 : 0;
  const unsubRate = delivered > 0 ? (unsubs / delivered) * 100 : 0;
  const complaintRate = delivered > 0 ? (complaints / delivered) * 100 : 0;
  const days = Number(inputs?.period_days || 30);

  // Funnel: sends → delivered → opens → clicks
  const funnelStages: Array<{ label: string; count: number; color: string }> = [
    { label: "Sent", count: sends, color: "#1A7DB5" },
    { label: "Delivered", count: delivered, color: "#0E78A0" },
    { label: "Opened", count: opens, color: "#EAB308" },
    { label: "Clicked", count: clicks, color: "#16A34A" },
  ];
  const maxStage = Math.max(1, ...funnelStages.map((s) => s.count));

  return (
    <>
      {/* Hero callout */}
      {sends === 0 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            No campaigns sent this period. Sender reputation + audience engagement signals decay after 30 days of silence — schedule at least one campaign in the next 7 days to maintain inbox-placement signals.
          </p>
        </div>
      ) : bounceRate > 5 ? (
        <div className="rounded-md border-l-4 border-rose-400 bg-rose-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-rose-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            <strong>Critical deliverability issue.</strong> Bounce rate is {bounceRate.toFixed(1)}% — above the 5% threshold that triggers ISP throttling. Continued sending will cause future campaigns to land in spam folders. <strong>Pause sending</strong> and clean the list before resuming.
          </p>
        </div>
      ) : openRate < 18 && sends >= 200 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            Open rate is <strong>{openRate.toFixed(1)}%</strong> across {fmtN(sends)} sends — below the 20-25% benchmark. Note that Apple MPP inflates raw open rates ~20%; your true engagement is likely worse than displayed. Subject-line A/B testing is the highest-leverage fix.
          </p>
        </div>
      ) : (
        <div className="rounded-md border-l-4 border-emerald-400 bg-emerald-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-emerald-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            {fmtN(sends)} campaign sends over {days} days. Open rate <strong>{openRate.toFixed(1)}%</strong> · click rate <strong>{clickRate.toFixed(2)}%</strong>. Deliverability metrics within healthy ranges — focus optimisation on segment-specific campaigns rather than broadcast tweaks.
          </p>
        </div>
      )}

      {/* KPI tiles */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Kpi label={`Sent (${days}d)`} value={fmtN(sends)} sub={`${fmtN(delivered)} delivered`} accent="#EF6C33" />
        <Kpi label="Open Rate" value={delivered > 0 ? `${openRate.toFixed(1)}%` : "—"} sub={`${fmtN(opens)} opens · vs ~22% benchmark`} accent={openRate >= 25 ? "#16A34A" : openRate >= 18 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Click Rate" value={delivered > 0 ? `${clickRate.toFixed(2)}%` : "—"} sub={`${fmtN(clicks)} clicks · CTOR ${ctorRate.toFixed(1)}%`} accent={clickRate >= 3 ? "#16A34A" : clickRate >= 2 ? "#EAB308" : "#DC2626"} />
        <Kpi label="List Hygiene" value={sends > 0 ? `${(100 - bounceRate).toFixed(1)}%` : "—"} sub={`${bounceRate.toFixed(2)}% bounce · ${unsubRate.toFixed(2)}% unsub`} accent={bounceRate < 2 && unsubRate < 0.3 ? "#16A34A" : bounceRate < 5 ? "#EAB308" : "#DC2626"} />
      </div>

      {/* Engagement funnel */}
      <div>
        <h3 className="text-sm font-bold text-slate-900 mb-2">Engagement funnel</h3>
        <div className="space-y-2">
          {funnelStages.map((s, i) => {
            const widthPct = (s.count / maxStage) * 100;
            const prevCount = i > 0 ? funnelStages[i - 1].count : s.count;
            const conversionFromPrev = prevCount > 0 && i > 0 ? Math.round((s.count / prevCount) * 100) : null;
            return (
              <div key={i} className="flex items-center gap-3">
                <div className="w-24 text-xs font-medium text-slate-700 flex-shrink-0">{s.label}</div>
                <div className="flex-1 h-6 rounded bg-slate-100 overflow-hidden relative">
                  <div className="h-full rounded transition-all" style={{ width: `${widthPct}%`, background: s.color }} />
                  <div className="absolute inset-0 flex items-center px-2 text-[10px] font-semibold text-slate-700">
                    {s.count > 0 && <span>{fmtN(s.count)}{conversionFromPrev != null ? ` · ${conversionFromPrev}% from previous` : ""}</span>}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Deliverability detail */}
      <div>
        <h3 className="text-sm font-bold text-slate-900 mb-2">Deliverability signals</h3>
        <div className="rounded-md border border-slate-200 overflow-hidden">
          <table className="w-full text-xs">
            <thead className="bg-slate-50">
              <tr>
                <th className="text-left px-3 py-2 font-semibold text-slate-600">Signal</th>
                <th className="text-right px-3 py-2 font-semibold text-slate-600">Count</th>
                <th className="text-right px-3 py-2 font-semibold text-slate-600">Rate</th>
                <th className="text-left px-3 py-2 font-semibold text-slate-600">Threshold</th>
              </tr>
            </thead>
            <tbody>
              <tr className="border-t border-slate-100">
                <td className="px-3 py-2 text-slate-900">Bounces</td>
                <td className="px-3 py-2 text-right text-slate-700 tabular-nums">{fmtN(bounces)}</td>
                <td className="px-3 py-2 text-right tabular-nums" style={{ color: bounceRate < 2 ? "#16A34A" : bounceRate < 5 ? "#EAB308" : "#DC2626" }}>{bounceRate.toFixed(2)}%</td>
                <td className="px-3 py-2 text-slate-500 text-[11px]">Warn at 2% · Critical at 5%</td>
              </tr>
              <tr className="border-t border-slate-100">
                <td className="px-3 py-2 text-slate-900">Unsubscribes</td>
                <td className="px-3 py-2 text-right text-slate-700 tabular-nums">{fmtN(unsubs)}</td>
                <td className="px-3 py-2 text-right tabular-nums" style={{ color: unsubRate < 0.3 ? "#16A34A" : unsubRate < 0.5 ? "#EAB308" : "#DC2626" }}>{unsubRate.toFixed(2)}%</td>
                <td className="px-3 py-2 text-slate-500 text-[11px]">Warn at 0.5%</td>
              </tr>
              <tr className="border-t border-slate-100">
                <td className="px-3 py-2 text-slate-900">Spam complaints</td>
                <td className="px-3 py-2 text-right text-slate-700 tabular-nums">{fmtN(complaints)}</td>
                <td className="px-3 py-2 text-right tabular-nums" style={{ color: complaintRate < 0.05 ? "#16A34A" : complaintRate < 0.1 ? "#EAB308" : "#DC2626" }}>{complaintRate.toFixed(3)}%</td>
                <td className="px-3 py-2 text-slate-500 text-[11px]">ISP threshold 0.1%</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </>
  );
}

// ── Lead Pipeline rich body ──────────────────────────────────────────
function LeadPipelineBody({ inputs }: { inputs: any }) {
  const funnel = inputs?.lead_funnel || [];
  const byStatus: Record<string, number> = Object.fromEntries(funnel.map((r: any) => [r.status, Number(r.n || 0)]));
  const total = funnel.reduce((s: number, r: any) => s + Number(r.n || 0), 0);
  const newLeads = (Number(byStatus.new || 0)) + (Number(byStatus.open || 0));
  const qualified = Number(byStatus.qualified || 0);
  const proposal = Number(byStatus.proposal_sent || byStatus.proposal || 0);
  const won = Number(byStatus.won || byStatus.converted || 0);
  const lost = Number(byStatus.lost || byStatus.disqualified || 0);
  const decisions = won + lost;
  const winRate = decisions > 0 ? (won / decisions) * 100 : 0;
  const qualRate = newLeads > 0 ? (qualified / newLeads) * 100 : 0;
  const days = Number(inputs?.period_days || 30);

  // Funnel stages, in order
  const stages: Array<{ label: string; count: number; color: string }> = [
    { label: "New / Open", count: newLeads, color: "#94A3B8" },
    { label: "Contacted", count: Number(byStatus.contacted || 0), color: "#1A7DB5" },
    { label: "Qualified", count: qualified, color: "#0E78A0" },
    { label: "Proposal", count: proposal, color: "#EAB308" },
    { label: "Won", count: won, color: "#16A34A" },
    { label: "Lost", count: lost, color: "#DC2626" },
  ];
  const maxStage = Math.max(1, ...stages.map((s) => s.count));

  return (
    <>
      {/* Hero callout */}
      {total === 0 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            No leads in the pipeline this period. Either no forms are mapping to lead creation, or every visitor is landing directly in your contact database without a qualifying lead stage. Inspect form-mapping + inbound-webhook deliveries.
          </p>
        </div>
      ) : winRate < 25 && decisions >= 5 ? (
        <div className="rounded-md border-l-4 border-rose-400 bg-rose-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-rose-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            Win rate is <strong>{winRate.toFixed(0)}%</strong> ({won} won of {decisions} decisions) — below the 25% floor most service businesses see. Either lead quality is weak, response time is too slow, or your discovery process isn't surfacing fit issues before quoting.
          </p>
        </div>
      ) : qualRate < 40 && newLeads >= 10 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            Only <strong>{qualRate.toFixed(0)}%</strong> of new leads make it to qualified — the biggest funnel leak is at lead → qualification. Auto-assign new leads and require a same-day response SLA to compress this stage.
          </p>
        </div>
      ) : (
        <div className="rounded-md border-l-4 border-emerald-400 bg-emerald-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-emerald-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            Pipeline this period: <strong>{fmtN(total)} leads</strong> · {qualified} qualified · {won} won{decisions > 0 ? ` (${winRate.toFixed(0)}% win rate)` : ""}. The funnel is moving — focus optimisation on whichever stage is dragging your composite score.
          </p>
        </div>
      )}

      {/* KPI tiles */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Kpi label={`Leads (${days}d)`} value={fmtN(total)} sub={`${(total / Math.max(days, 1)).toFixed(1)}/day`} accent="#EF6C33" />
        <Kpi label="Win Rate" value={decisions > 0 ? `${winRate.toFixed(0)}%` : "—"} sub={`${won} won of ${decisions} decisions`} accent={winRate >= 35 ? "#16A34A" : winRate >= 20 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Qualification Rate" value={newLeads > 0 ? `${qualRate.toFixed(0)}%` : "—"} sub={`${qualified} qual of ${newLeads} new`} accent={qualRate >= 50 ? "#16A34A" : qualRate >= 30 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Loss Share" value={total > 0 ? `${((lost / total) * 100).toFixed(0)}%` : "—"} sub={`${lost} of ${total} marked lost`} accent={(lost / Math.max(total, 1)) < 0.2 ? "#16A34A" : (lost / Math.max(total, 1)) < 0.35 ? "#EAB308" : "#DC2626"} />
      </div>

      {/* Funnel stage visualization */}
      <div>
        <h3 className="text-sm font-bold text-slate-900 mb-2">Funnel by stage</h3>
        <div className="space-y-2">
          {stages.map((s, i) => {
            const widthPct = (s.count / maxStage) * 100;
            const sharePct = total > 0 ? Math.round((s.count / total) * 100) : 0;
            return (
              <div key={i} className="flex items-center gap-3">
                <div className="w-28 text-xs font-medium text-slate-700 flex-shrink-0">{s.label}</div>
                <div className="flex-1 h-6 rounded bg-slate-100 overflow-hidden relative">
                  <div className="h-full rounded transition-all" style={{ width: `${widthPct}%`, background: s.color }} />
                  <div className="absolute inset-0 flex items-center px-2 text-[10px] font-semibold text-slate-700">
                    {s.count > 0 && <span>{fmtN(s.count)} · {sharePct}%</span>}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Sources (if any) */}
      {Array.isArray(inputs?.top_sources) && inputs.top_sources.length > 0 && (
        <div>
          <h3 className="text-sm font-bold text-slate-900 mb-2">Lead sources</h3>
          <div className="rounded-md border border-slate-200 overflow-hidden">
            <table className="w-full text-xs">
              <thead className="bg-slate-50">
                <tr>
                  <th className="text-left px-3 py-2 font-semibold text-slate-600">Source</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Volume</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Active rate</th>
                </tr>
              </thead>
              <tbody>
                {inputs.top_sources.slice(0, 8).map((s: any, i: number) => {
                  const n = Number(s.n || 0);
                  const act = Number(s.active_count || 0);
                  const rate = n > 0 ? (act / n) * 100 : 0;
                  return (
                    <tr key={i} className="border-t border-slate-100">
                      <td className="px-3 py-2 text-slate-900">{s.source || "(unknown)"}</td>
                      <td className="px-3 py-2 text-right text-slate-700 tabular-nums">{fmtN(n)}</td>
                      <td className="px-3 py-2 text-right tabular-nums" style={{ color: rate >= 70 ? "#16A34A" : rate >= 40 ? "#EAB308" : "#DC2626" }}>
                        {rate.toFixed(0)}%
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </>
  );
}

// ── Contact Health rich body ─────────────────────────────────────────
function ContactHealthBody({ inputs }: { inputs: any }) {
  const t = inputs?.contact_totals || {};
  const recent = Number(inputs?.contact_recent?.new_contacts || 0);
  const active = Number(t.active || 0);
  const total = Number(t.total || 0);
  const email = Number(t.with_email || 0);
  const phone = Number(t.with_phone || 0);
  const opts = Number(t.sms_opt_outs || 0);
  const growthPct = active > 0 ? ((recent / active) * 100) : 0;
  const emailPct = active > 0 ? ((email / active) * 100) : 0;
  const phonePct = active > 0 ? ((phone / active) * 100) : 0;
  const days = Number(inputs?.period_days || 30);

  const sources = inputs?.top_sources || [];
  const tags = inputs?.top_tags || [];

  return (
    <>
      {/* Hero insight callout */}
      {active === 0 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            No active contacts in SPARK yet. Either import your existing contact list or wire a form to capture inbound leads — every other Contact Health observation depends on this baseline.
          </p>
        </div>
      ) : recent === 0 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            <strong>0 new contacts</strong> in the last {days} days. Your acquisition funnel is dry — every day without inbound captures compounds into a lower revenue floor 60-90 days out. Inspect the top entry-page forms first.
          </p>
        </div>
      ) : growthPct < 2 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            Contact base grew <strong>{growthPct.toFixed(1)}%</strong> over {days} days ({recent} new on a base of {active} active). Below the 5% benchmark for service businesses — at this pace, doubling the contact base takes ~{Math.round(70 / Math.max(growthPct, 0.5))} months.
          </p>
        </div>
      ) : (
        <div className="rounded-md border-l-4 border-emerald-400 bg-emerald-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-emerald-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            Contact base grew <strong>{growthPct.toFixed(1)}%</strong> over {days} days. {recent} new contacts joined an active base of {fmtN(active)} — sustainable growth within the healthy range.
          </p>
        </div>
      )}

      {/* KPI tiles */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Kpi label="Active Contacts" value={fmtN(active)} sub={`${fmtN(total)} total in system`} accent="#EF6C33" />
        <Kpi label={`New (${days}d)`} value={fmtN(recent)} sub={`${growthPct.toFixed(1)}% growth rate`} accent={growthPct >= 5 ? "#16A34A" : growthPct >= 2 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Email Coverage" value={`${Math.round(emailPct)}%`} sub={`${fmtN(email)} of ${fmtN(active)}`} accent={emailPct >= 70 ? "#16A34A" : emailPct >= 50 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Phone Coverage" value={`${Math.round(phonePct)}%`} sub={`${fmtN(phone)} of ${fmtN(active)} · ${fmtN(opts)} opt-outs`} accent={phonePct >= 50 ? "#16A34A" : phonePct >= 30 ? "#EAB308" : "#DC2626"} />
      </div>

      {/* Source distribution table */}
      {sources.length > 0 && (
        <div>
          <h3 className="text-sm font-bold text-slate-900 mb-2">Acquisition sources</h3>
          <div className="rounded-md border border-slate-200 overflow-hidden">
            <table className="w-full text-xs">
              <thead className="bg-slate-50">
                <tr>
                  <th className="text-left px-3 py-2 font-semibold text-slate-600">Source</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Contacts</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Active</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Active rate</th>
                </tr>
              </thead>
              <tbody>
                {sources.slice(0, 10).map((s: any, i: number) => {
                  const n = Number(s.n || 0);
                  const act = Number(s.active_count || 0);
                  const rate = n > 0 ? (act / n) * 100 : 0;
                  return (
                    <tr key={i} className="border-t border-slate-100">
                      <td className="px-3 py-2 text-slate-900">{s.source || "(unknown)"}</td>
                      <td className="px-3 py-2 text-right text-slate-700 tabular-nums">{fmtN(n)}</td>
                      <td className="px-3 py-2 text-right text-slate-700 tabular-nums">{fmtN(act)}</td>
                      <td className="px-3 py-2 text-right tabular-nums" style={{ color: rate >= 70 ? "#16A34A" : rate >= 40 ? "#EAB308" : "#DC2626" }}>
                        {rate.toFixed(0)}%
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Top tags */}
      {tags.length > 0 && (
        <div>
          <h3 className="text-sm font-bold text-slate-900 mb-2">Top tags</h3>
          <div className="flex flex-wrap gap-2">
            {tags.slice(0, 12).map((tag: any, i: number) => (
              <span key={i} className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-slate-100 text-slate-700 text-xs">
                <span className="font-medium">{tag.name}</span>
                <span className="text-[10px] text-slate-500">{fmtN(Number(tag.n))}</span>
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Channel reachability summary */}
      <div>
        <h3 className="text-sm font-bold text-slate-900 mb-2">Channel reachability</h3>
        <div className="grid grid-cols-2 gap-3">
          <ReachBar label="Email" pct={emailPct} count={email} total={active} color="#1A7DB5" />
          <ReachBar label="SMS" pct={phonePct} count={phone} total={active} color="#EF6C33" />
        </div>
      </div>
    </>
  );
}

// ── Marketing Attribution rich body ──────────────────────────────────
function MarketingAttribBody({ inputs }: { inputs: any }) {
  const sources = (inputs?.top_sources || []).filter((s: any) => s.source);
  const total = sources.reduce((s: number, r: any) => s + Number(r.n || 0), 0);
  const top = sources[0];
  const topShare = total > 0 && top ? (Number(top.n || 0) / total) * 100 : 0;

  return (
    <>
      {sources.length === 0 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">No sourced contacts this period. Either acquisition channels stopped producing, or source attribution isn't being captured at intake. Inspect form UTM capture + inbound webhooks.</p>
        </div>
      ) : topShare > 60 ? (
        <div className="rounded-md border-l-4 border-rose-400 bg-rose-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-rose-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed"><strong>{topShare.toFixed(0)}% concentration risk.</strong> Most contacts come from a single channel ({top.source}). A change in that channel's algorithm or pricing would halve your inbound flow overnight.</p>
        </div>
      ) : (
        <div className="rounded-md border-l-4 border-emerald-400 bg-emerald-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-emerald-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">{sources.length} acquisition channels active. Leading source <strong>{top.source}</strong> at {topShare.toFixed(0)}% share — diversified enough that no single channel can take you out.</p>
        </div>
      )}

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Kpi label="Channels" value={String(sources.length)} sub="active sources" accent="#EF6C33" />
        <Kpi label="Sourced Contacts" value={fmtN(total)} sub="this period" accent="#1A7DB5" />
        <Kpi label="Top Source Share" value={total > 0 ? `${topShare.toFixed(0)}%` : "—"} sub={top?.source || "—"} accent={topShare < 40 ? "#16A34A" : topShare < 60 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Diversity Score" value={String(Math.min(100, sources.length * 12 + Math.round((1 - topShare / 100) * 50)))} sub="0-100 channel mix health" accent="#0E78A0" />
      </div>

      {sources.length > 0 && (
        <div>
          <h3 className="text-sm font-bold text-slate-900 mb-2">Acquisition channel breakdown</h3>
          <div className="rounded-md border border-slate-200 overflow-hidden">
            <table className="w-full text-xs">
              <thead className="bg-slate-50">
                <tr>
                  <th className="text-left px-3 py-2 font-semibold text-slate-600">Source</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Contacts</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Share</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Active rate</th>
                </tr>
              </thead>
              <tbody>
                {sources.slice(0, 10).map((s: any, i: number) => {
                  const n = Number(s.n || 0);
                  const act = Number(s.active_count || 0);
                  const share = total > 0 ? (n / total) * 100 : 0;
                  const rate = n > 0 ? (act / n) * 100 : 0;
                  return (
                    <tr key={i} className="border-t border-slate-100">
                      <td className="px-3 py-2 text-slate-900">{s.source}</td>
                      <td className="px-3 py-2 text-right tabular-nums">{fmtN(n)}</td>
                      <td className="px-3 py-2 text-right tabular-nums">{share.toFixed(0)}%</td>
                      <td className="px-3 py-2 text-right tabular-nums" style={{ color: rate >= 70 ? "#16A34A" : rate >= 40 ? "#EAB308" : "#DC2626" }}>{rate.toFixed(0)}%</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </>
  );
}

// ── Segmentation rich body ───────────────────────────────────────────
function SegmentationBody({ inputs }: { inputs: any }) {
  const segs = inputs?.segments || [];
  const tags = inputs?.top_tags || [];
  const active = Number(inputs?.contact_totals?.active || 0);
  const totalMembers = segs.reduce((s: number, r: any) => s + Number(r.members || 0), 0);
  const coverage = active > 0 ? Math.min(1, totalMembers / active) * 100 : 0;

  return (
    <>
      {segs.length === 0 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">No segments defined. Without segmentation every campaign goes to every contact — engagement falls and unsubscribes rise. Segments are the foundation of every lifecycle marketing capability.</p>
        </div>
      ) : coverage < 40 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">Segment coverage is <strong>{coverage.toFixed(0)}%</strong>. Most contacts fall outside any defined segment — the majority of your audience can't be reached by targeted campaigns.</p>
        </div>
      ) : (
        <div className="rounded-md border-l-4 border-emerald-400 bg-emerald-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-emerald-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">{segs.length} segments cover <strong>{coverage.toFixed(0)}%</strong> of active contacts ({fmtN(totalMembers)} memberships across {fmtN(active)} active). Solid targeting foundation.</p>
        </div>
      )}

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Kpi label="Segments" value={String(segs.length)} sub="defined" accent="#EF6C33" />
        <Kpi label="Coverage" value={active > 0 ? `${coverage.toFixed(0)}%` : "—"} sub="of active contacts" accent={coverage >= 70 ? "#16A34A" : coverage >= 40 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Tag Library" value={String(tags.length)} sub="unique tags" accent={tags.length >= 8 ? "#16A34A" : tags.length >= 3 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Top Segment" value={segs[0]?.name || "—"} sub={segs[0] ? `${fmtN(Number(segs[0].members))} members` : ""} accent="#1A7DB5" />
      </div>

      {segs.length > 0 && (
        <div>
          <h3 className="text-sm font-bold text-slate-900 mb-2">Segments</h3>
          <div className="space-y-1.5">
            {segs.slice(0, 10).map((s: any, i: number) => {
              const members = Number(s.members || 0);
              const share = active > 0 ? (members / active) * 100 : 0;
              return (
                <div key={i} className="flex items-center gap-3">
                  <div className="w-40 text-xs text-slate-700 truncate">{s.name}</div>
                  <div className="flex-1 h-5 rounded bg-slate-100 overflow-hidden relative">
                    <div className="h-full rounded" style={{ width: `${Math.min(100, share)}%`, background: "#1A7DB5" }} />
                    <div className="absolute inset-0 flex items-center px-2 text-[10px] font-semibold text-slate-700">{fmtN(members)} · {share.toFixed(0)}%</div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {tags.length > 0 && (
        <div>
          <h3 className="text-sm font-bold text-slate-900 mb-2">Top tags ({tags.length} total)</h3>
          <div className="flex flex-wrap gap-2">
            {tags.slice(0, 16).map((t: any, i: number) => (
              <span key={i} className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-slate-100 text-slate-700 text-xs">
                <span className="font-medium">{t.name}</span>
                <span className="text-[10px] text-slate-500">{fmtN(Number(t.n))}</span>
              </span>
            ))}
          </div>
        </div>
      )}
    </>
  );
}

// ── Automation Effectiveness rich body ───────────────────────────────
function AutomationEffBody({ inputs }: { inputs: any }) {
  const a = inputs?.automations || { total: 0, active: 0, total_executions: 0 };
  const total = Number(a.total || 0);
  const active = Number(a.active || 0);
  const execs = Number(a.total_executions || 0);
  const activeRate = total > 0 ? (active / total) * 100 : 0;
  const perAuto = active > 0 ? execs / active : 0;

  return (
    <>
      {total === 0 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">No automations defined. The single biggest SPARK value-add is replacing manual follow-up with deterministic automation — start with a new-lead welcome sequence.</p>
        </div>
      ) : activeRate < 50 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">Only <strong>{active} of {total}</strong> automations are active. Paused automations add cognitive load without producing value — audit and either fix or delete.</p>
        </div>
      ) : perAuto < 5 && active >= 3 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">{active} active automations averaging <strong>{perAuto.toFixed(1)} executions each</strong> — running but rarely firing. Trigger conditions likely don't match real events.</p>
        </div>
      ) : (
        <div className="rounded-md border-l-4 border-emerald-400 bg-emerald-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-emerald-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">{active} active automations, <strong>{fmtN(execs)} total executions</strong> ({perAuto.toFixed(0)} avg each). Automations are doing real work.</p>
        </div>
      )}

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Kpi label="Total Automations" value={String(total)} sub={`${active} active`} accent="#EF6C33" />
        <Kpi label="Active Rate" value={total > 0 ? `${activeRate.toFixed(0)}%` : "—"} sub="of total defined" accent={activeRate >= 80 ? "#16A34A" : activeRate >= 50 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Total Executions" value={fmtN(execs)} sub="across all automations" accent="#1A7DB5" />
        <Kpi label="Execs/Automation" value={active > 0 ? perAuto.toFixed(1) : "—"} sub="avg activity per active" accent={perAuto >= 50 ? "#16A34A" : perAuto >= 5 ? "#EAB308" : "#DC2626"} />
      </div>

      <div className="rounded-md border border-slate-200 bg-slate-50 p-4 text-xs text-slate-700 space-y-2">
        <div className="font-bold text-slate-900 text-sm mb-2">Recommended starter automations</div>
        <div>• New-contact welcome sequence (3-message, 14-day arc)</div>
        <div>• Form-abandoned recovery (single message, 24-hour delay)</div>
        <div>• Post-job thank-you + review request (2-message, fired by completed event)</div>
        <div>• 30-day non-engagement check-in (fires when score drops below threshold)</div>
        <div>• 90-day dormancy re-engagement (multi-step win-back with incentive)</div>
      </div>
    </>
  );
}

// ── Retention Risk rich body ─────────────────────────────────────────
function RetentionRiskBody({ inputs }: { inputs: any }) {
  const r = inputs?.retention || { scored_contacts: 0, low_score: 0, mid_score: 0, high_score: 0 };
  const total = Number(r.scored_contacts || 0);
  const high = Number(r.high_score || 0);
  const mid = Number(r.mid_score || 0);
  const low = Number(r.low_score || 0);
  const highPct = total > 0 ? (high / total) * 100 : 0;
  const midPct = total > 0 ? (mid / total) * 100 : 0;
  const lowPct = total > 0 ? (low / total) * 100 : 0;

  return (
    <>
      {total === 0 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">No scored contacts. Behavioural lead scoring is the foundation for retention risk identification — without scores, churn happens before you see it.</p>
        </div>
      ) : lowPct > 40 ? (
        <div className="rounded-md border-l-4 border-rose-400 bg-rose-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-rose-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed"><strong>{lowPct.toFixed(0)}% retention risk.</strong> {fmtN(low)} of {fmtN(total)} scored contacts are low-engagement — your churn pool. Plan a structured win-back now, not after they churn.</p>
        </div>
      ) : highPct >= 25 ? (
        <div className="rounded-md border-l-4 border-emerald-400 bg-emerald-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-emerald-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed"><strong>{highPct.toFixed(0)}% high-engagement</strong> ({fmtN(high)} champions). Protect them with exclusive offers, early access, or a referral incentive — champions are 2-3x more likely to refer than mid-tier contacts.</p>
        </div>
      ) : (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">Score distribution: {highPct.toFixed(0)}% high · {midPct.toFixed(0)}% mid · {lowPct.toFixed(0)}% low. Mid-tier is where activation campaigns produce the most lift.</p>
        </div>
      )}

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Kpi label="Scored Contacts" value={fmtN(total)} sub="in scoring system" accent="#EF6C33" />
        <Kpi label="High Tier (≥70)" value={total > 0 ? `${highPct.toFixed(0)}%` : "—"} sub={`${fmtN(high)} champions`} accent={highPct >= 20 ? "#16A34A" : "#EAB308"} />
        <Kpi label="Mid Tier (30-69)" value={total > 0 ? `${midPct.toFixed(0)}%` : "—"} sub={`${fmtN(mid)} active but not deeply engaged`} accent="#1A7DB5" />
        <Kpi label="Low Tier (<30)" value={total > 0 ? `${lowPct.toFixed(0)}%` : "—"} sub={`${fmtN(low)} retention-risk pool`} accent={lowPct < 25 ? "#16A34A" : lowPct < 40 ? "#EAB308" : "#DC2626"} />
      </div>

      {total > 0 && (
        <div>
          <h3 className="text-sm font-bold text-slate-900 mb-2">Score distribution</h3>
          <div className="space-y-2">
            {[
              { label: "High (≥70)", count: high, pct: highPct, color: "#16A34A" },
              { label: "Mid (30-69)", count: mid, pct: midPct, color: "#EAB308" },
              { label: "Low (<30)", count: low, pct: lowPct, color: "#DC2626" },
            ].map((tier, i) => (
              <div key={i} className="flex items-center gap-3">
                <div className="w-28 text-xs text-slate-700">{tier.label}</div>
                <div className="flex-1 h-6 rounded bg-slate-100 overflow-hidden relative">
                  <div className="h-full rounded" style={{ width: `${tier.pct}%`, background: tier.color }} />
                  <div className="absolute inset-0 flex items-center px-2 text-[10px] font-semibold text-slate-700">{fmtN(tier.count)} · {tier.pct.toFixed(0)}%</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </>
  );
}

// ── Revenue Attribution rich body ────────────────────────────────────
function RevenueAttribBody({ inputs }: { inputs: any }) {
  const sources = inputs?.revenue_attribution || [];
  const totalLtv = sources.reduce((s: number, r: any) => s + Number(r.total_ltv || 0), 0);
  const totalContacts = sources.reduce((s: number, r: any) => s + Number(r.contacts || 0), 0);
  const avgLtv = totalContacts > 0 ? totalLtv / totalContacts : 0;
  const top = sources[0];
  const topShare = totalLtv > 0 && top ? Number(top.total_ltv || 0) / totalLtv * 100 : 0;

  return (
    <>
      {totalLtv === 0 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">No revenue attribution data yet. Either lifetime_value isn't populating on contact records (check OLIVER → SPARK sync) or no jobs have completed this period.</p>
        </div>
      ) : topShare > 65 ? (
        <div className="rounded-md border-l-4 border-rose-400 bg-rose-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-rose-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed"><strong>{topShare.toFixed(0)}% revenue concentration risk.</strong> {top.source} produces ${fmtN(Number(top.total_ltv || 0))} — most of your LTV. A change to that channel would halve revenue overnight.</p>
        </div>
      ) : (
        <div className="rounded-md border-l-4 border-emerald-400 bg-emerald-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-emerald-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">${fmtN(totalLtv)} attributed lifetime value across <strong>{fmtN(totalContacts)} customers</strong> from {sources.length} sources. Average LTV: ${fmtN(avgLtv)}.</p>
        </div>
      )}

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Kpi label="Total Attributed LTV" value={`$${fmtN(totalLtv)}`} sub={`${fmtN(totalContacts)} customers`} accent="#16A34A" />
        <Kpi label="Avg LTV / Customer" value={avgLtv > 0 ? `$${fmtN(avgLtv)}` : "—"} sub="across all sources" accent={avgLtv >= 2000 ? "#16A34A" : avgLtv >= 500 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Revenue Sources" value={String(sources.length)} sub="actively producing" accent="#EF6C33" />
        <Kpi label="Top Source Share" value={totalLtv > 0 ? `${topShare.toFixed(0)}%` : "—"} sub={top?.source || "—"} accent={topShare < 40 ? "#16A34A" : topShare < 65 ? "#EAB308" : "#DC2626"} />
      </div>

      {sources.length > 0 && (
        <div>
          <h3 className="text-sm font-bold text-slate-900 mb-2">Revenue by source</h3>
          <div className="rounded-md border border-slate-200 overflow-hidden">
            <table className="w-full text-xs">
              <thead className="bg-slate-50">
                <tr>
                  <th className="text-left px-3 py-2 font-semibold text-slate-600">Source</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">LTV</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Customers</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Avg LTV</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Share</th>
                </tr>
              </thead>
              <tbody>
                {sources.slice(0, 10).map((s: any, i: number) => {
                  const ltv = Number(s.total_ltv || 0);
                  const ct = Number(s.contacts || 0);
                  const avg = ct > 0 ? ltv / ct : 0;
                  const share = totalLtv > 0 ? (ltv / totalLtv) * 100 : 0;
                  return (
                    <tr key={i} className="border-t border-slate-100">
                      <td className="px-3 py-2 text-slate-900">{s.source || "(unknown)"}</td>
                      <td className="px-3 py-2 text-right tabular-nums font-medium text-slate-900">${fmtN(ltv)}</td>
                      <td className="px-3 py-2 text-right tabular-nums">{fmtN(ct)}</td>
                      <td className="px-3 py-2 text-right tabular-nums">${fmtN(avg)}</td>
                      <td className="px-3 py-2 text-right tabular-nums" style={{ color: share > 50 ? "#DC2626" : share > 30 ? "#EAB308" : "#16A34A" }}>{share.toFixed(0)}%</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </>
  );
}

// ── Generic fallback body ────────────────────────────────────────────
function GenericBody({ report }: { report: SparkReportAnalysis }) {
  const numericInputs = report.scoreInputs.filter((s) => s.value !== null && s.value !== undefined);
  if (numericInputs.length === 0) return null;
  return (
    <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
      {numericInputs.slice(0, 4).map((k) => (
        <Kpi
          key={k.key}
          label={k.key}
          value={String(k.value)}
          sub={`${Math.round(k.weight * 100)}% of score`}
          accent="#EF6C33"
        />
      ))}
    </div>
  );
}

// ── UI atoms ─────────────────────────────────────────────────────────
function Kpi({ label, value, sub, accent }: { label: string; value: string; sub: string; accent: string }) {
  return (
    <div className="rounded-md border border-slate-200 bg-white px-3 py-2" style={{ borderTopWidth: 3, borderTopColor: accent }}>
      <div className="text-[10px] uppercase font-semibold text-slate-500 tracking-wide">{label}</div>
      <div className="text-lg font-bold text-slate-900 tabular-nums mt-0.5">{value}</div>
      <div className="text-[10px] text-slate-400 mt-0.5">{sub}</div>
    </div>
  );
}

function ReachBar({ label, pct, count, total, color }: { label: string; pct: number; count: number; total: number; color: string }) {
  return (
    <div className="rounded-md border border-slate-200 bg-white p-3">
      <div className="flex items-center justify-between mb-1">
        <span className="text-xs font-semibold text-slate-700">{label}</span>
        <span className="text-xs tabular-nums text-slate-600">{Math.round(pct)}%</span>
      </div>
      <div className="h-2 rounded-full bg-slate-100 overflow-hidden">
        <div className="h-full rounded-full transition-all" style={{ width: `${Math.min(100, Math.max(0, pct))}%`, background: color }} />
      </div>
      <div className="text-[10px] text-slate-400 mt-1.5">{fmtN(count)} of {fmtN(total)} active contacts</div>
    </div>
  );
}

function fmtN(n: number): string {
  if (!isFinite(n)) return "0";
  return n.toLocaleString();
}

export default SparkReportDetailModal;
